begin;
insert into auth.users(id) values('99000000-0000-4000-8000-000000000013'),('99100000-0000-4000-8000-000000000013');
select set_config('request.jwt.claim.sub','99000000-0000-4000-8000-000000000013',true);
update private.ai_runtime set server_token_hash=sha256(convert_to('fixture-server-proof','UTF8')),pricing_reviewed_at=clock_timestamp();
set local role authenticated;
do $$declare p uuid;l uuid;l2 uuid;stamp timestamptz;items jsonb;req uuid=gen_random_uuid();batch jsonb;c uuid=gen_random_uuid();u uuid=gen_random_uuid();a uuid=gen_random_uuid();op jsonb;begin
 p=public.manage_page(null,'Chat fixture','',false);
 insert into public.leads(page_id,business_name,notes) values(p,'Skin clinic','Provides skin treatments') returning id,updated_at into l,stamp;
 insert into public.leads(page_id,business_name,notes) values(p,'Hardware shop','Sells tools') returning id into l2;
 select jsonb_agg(jsonb_build_object('id',id,'expected',updated_at) order by id) into items from public.leads where page_id=p;
 if public.delete_lead_selection(req,items)<>2 or public.delete_lead_selection(req,items)<>2 then raise exception 'Selection count or retry failed';end if;
 if exists(select 1 from public.leads where page_id=p and deleted_at is null) then raise exception 'Selection deletion missed targets';end if;
 perform public.undo_lead_selection(req);perform public.undo_lead_selection(req);
 if (select count(*) from public.leads where page_id=p and deleted_at is null)<>2 then raise exception 'Selection undo failed';end if;
 begin perform public.delete_lead_selection(gen_random_uuid(),items);raise exception 'Stale preview accepted';exception when serialization_failure then null;end;
 if exists(select 1 from public.leads where page_id=p and deleted_at is not null) then raise exception 'Stale selection did not roll back atomically';end if;
 batch=public.commit_import(gen_random_uuid(),p,null,'append','chat.csv','[{"business_name":"Imported fixture"}]',1,0);
 perform public.record_chat_import(c,u,a,(batch->>'id')::uuid);perform public.record_chat_import(c,u,a,(batch->>'id')::uuid);
 if (select count(*) from public.ai_chat_messages where conversation_id=c)<>2 then raise exception 'Import retry duplicated messages';end if;
 if not exists(select 1 from public.ai_chat_messages where id=a and artifact->>'imported'='1') then raise exception 'Import summary did not use DB counts';end if;
 op=public.ai_stage(gen_random_uuid(),jsonb_build_object('action','search','pageId',p,'importId',null,'selectedIds','[]'::jsonb,'previousId',null,'undoId',null,'filter',jsonb_build_object('logic','and','groups','[]'::jsonb),'changes','{}'::jsonb,'destinationId',null),'fixture-server-proof');
 select updated_at into stamp from public.leads where id=l;
 perform public.save_ai_relevance((op->>'id')::uuid,jsonb_build_object('criteria','skin clinics','offset',0,'total',3,'items',jsonb_build_array(jsonb_build_object('id',l,'name','Skin clinic','expected',stamp,'classification','relevant','reason','Skin services','evidence','skin treatments'))),'fixture-server-proof');
 if public.ai_plan_result((op->>'id')::uuid)#>>'{analysis,criteria}'<>'skin clinics' then raise exception 'Analysis not retained';end if;
 perform set_config('request.jwt.claim.sub','99100000-0000-4000-8000-000000000013',true);
 begin perform public.delete_ai_conversation(c);raise exception 'Cross-owner chat deletion accepted';exception when insufficient_privilege then null;end;
 begin perform public.undo_chat_import(c,(batch->>'id')::uuid);raise exception 'Cross-owner import undo accepted';exception when insufficient_privilege then null;end;
 begin perform public.undo_lead_selection(req);raise exception 'Cross-owner selection undo accepted';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub','99000000-0000-4000-8000-000000000013',true);
 perform public.undo_chat_import(c,(batch->>'id')::uuid);
 if public.ai_plan_result((op->>'id')::uuid)?'analysis' then raise exception 'Purged evidence retained';end if;
 perform public.delete_ai_conversation(c);
 if exists(select 1 from public.ai_chat_messages where conversation_id=c) or (select count(*) from public.leads where page_id=p and deleted_at is null)<>2 then raise exception 'Chat deletion changed leads or retained messages';end if;
 raise notice 'PASS: atomic selected deletion, stale snapshots, retry/undo, DB-grounded chat imports, private analysis, cross-owner rejection, purge redaction and chat-only deletion';
end $$;
rollback;
